export function makeBusinessSuggestionReply(id, question) {
  const item = businessSuggestions.find(item => item.id === id)
  if (!item?.answer) return null
  const source = /依据|口径|数据来源/.test(question)
  const sections = source ? item.answer.sections.slice(0, 1) : item.answer.sections.slice(-2)
  return {
    title: source ? '本次使用的业务范围与数据口径' : `继续核查${item.scope}`,
    reasoning: ['沿用本次已带入的业务对象、期间和演示快照。'],
    sections: [...sections, { heading: '继续办理', paragraphs: ['可基于以上清单核实业务。本次原型使用固定示例回答，自由追问暂展示本业务范围内的核查建议。'] }],
  }
}
